import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_14_actor_critic_roles.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_14_td_advantage.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_14_update_loop.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_14_gae.png",c="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_14_driving_safety.png",f=JSON.parse('{"title":"演员负责行动，评论家负责打分：Actor-Critic 为什么能边走边学","description":"REINFORCE（蒙特卡洛策略梯度）要等完整回合结束，才知道每个动作之后的真实未来回报。长轨迹中的随机奖励全部进入梯度权重，估计往往高方差。Actor-Critic（演员—评论家）把学习任务拆成两个角色：Actor（演员）用策略 \\\\(\\\\pi\\\\theta(a|s)\\\\) 选择动作，Critic（评论家","frontmatter":{"title":"演员负责行动，评论家负责打分：Actor-Critic 为什么能边走边学","description":"REINFORCE（蒙特卡洛策略梯度）要等完整回合结束，才知道每个动作之后的真实未来回报。长轨迹中的随机奖励全部进入梯度权重，估计往往高方差。Actor-Critic（演员—评论家）把学习任务拆成两个角色：Actor（演员）用策略 \\\\(\\\\pi\\\\theta(a|s)\\\\) 选择动作，Critic（评论家","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":14,"source":"2026-08-13/rl_series_14_actor_critic.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_14_actor_critic_roles.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-14-actor-critic"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"演员负责行动，评论家负责打分：Actor-Critic 为什么能边走边学"}],["meta",{"property":"og:description","content":"REINFORCE（蒙特卡洛策略梯度）要等完整回合结束，才知道每个动作之后的真实未来回报。长轨迹中的随机奖励全部进入梯度权重，估计往往高方差。Actor-Critic（演员—评论家）把学习任务拆成两个角色：Actor（演员）用策略 \\\\(\\\\pi\\\\theta(a|s)\\\\) 选择动作，Critic（评论家"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-14-actor-critic"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_14_actor_critic_roles.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"演员负责行动，评论家负责打分：Actor-Critic 为什么能边走边学"}],["meta",{"name":"twitter:description","content":"REINFORCE（蒙特卡洛策略梯度）要等完整回合结束，才知道每个动作之后的真实未来回报。长轨迹中的随机奖励全部进入梯度权重，估计往往高方差。Actor-Critic（演员—评论家）把学习任务拆成两个角色：Actor（演员）用策略 \\\\(\\\\pi\\\\theta(a|s)\\\\) 选择动作，Critic（评论家"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_14_actor_critic_roles.png"}]],"prev":{"text":"不再从 Q 值里挑动作：策略梯度怎样直接学会决策","link":"/rl/rl-series-13-policy-gradient-reinforce"},"next":{"text":"同一批数据多学几轮，策略为什么会崩？PPO 的裁剪目标讲透了","link":"/rl/rl-series-15-ppo"}},"headers":[],"relativePath":"rl/rl-series-14-actor-critic.md","filePath":"rl/rl-series-14-actor-critic.md","lastUpdated":null}'),d={name:"rl/rl-series-14-actor-critic.md"};function s(p,a,_,u,b,q){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="演员负责行动-评论家负责打分-actor-critic-为什么能边走边学" tabindex="-1">演员负责行动，评论家负责打分：Actor-Critic 为什么能边走边学 <a class="header-anchor" href="#演员负责行动-评论家负责打分-actor-critic-为什么能边走边学" aria-label="Permalink to &quot;演员负责行动，评论家负责打分：Actor-Critic 为什么能边走边学&quot;">​</a></h1><p>REINFORCE（蒙特卡洛策略梯度）要等完整回合结束，才知道每个动作之后的真实未来回报。长轨迹中的随机奖励全部进入梯度权重，估计往往高方差。Actor-Critic（演员—评论家）把学习任务拆成两个角色：Actor（演员）用策略 (\\pi_\\theta(a|s)) 选择动作，Critic（评论家）用价值函数评估当前策略，并把 Temporal-Difference Error（时序差分误差）或 Advantage（优势）交给演员更新。</p><p>这并不是把两个神经网络并排摆放就完成了。评论家评价的是当前演员，而不是环境中永久不变的真值；演员改变后，评论家的目标也会移动。演员学习率、评论家学习率、采样策略、终止语义和共享特征共同构成耦合系统。Actor-Critic 用自举降低方差并提高更新频率，同时引入价值估计偏差和双网络稳定性问题。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-演员输出策略-评论家输出价值" tabindex="-1">1.1 演员输出策略，评论家输出价值 <a class="header-anchor" href="#_1-1-演员输出策略-评论家输出价值" aria-label="Permalink to &quot;1.1 演员输出策略，评论家输出价值&quot;">​</a></h3><p>演员决定动作分布，评论家估计 (V^\\pi(s)) 或 (Q^\\pi(s,a))。评论家只在训练中提供评价信号，最终动作仍由演员产生。</p><h3 id="_1-2-td-误差可以近似一步优势" tabindex="-1">1.2 TD 误差可以近似一步优势 <a class="header-anchor" href="#_1-2-td-误差可以近似一步优势" aria-label="Permalink to &quot;1.2 TD 误差可以近似一步优势&quot;">​</a></h3><p>$$ \\delta_t=R_{t+1}+\\gamma V_\\phi(S_{t+1})-V_\\phi(S_t) $$</p><p>在合适条件下，(\\delta_t) 可作为当前动作相对状态基线的样本优势，正值提高动作概率，负值降低动作概率。</p><h3 id="_1-3-更频繁更新换来了自举偏差" tabindex="-1">1.3 更频繁更新换来了自举偏差 <a class="header-anchor" href="#_1-3-更频繁更新换来了自举偏差" aria-label="Permalink to &quot;1.3 更频繁更新换来了自举偏差&quot;">​</a></h3><p>评论家无需等待终点即可生成目标，方差通常低于完整回报；但下一状态价值若估错，偏差会进入演员梯度并沿自举传播。</p><h3 id="_1-4-a2c-与-a3c-的差异主要在数据并行方式" tabindex="-1">1.4 A2C 与 A3C 的差异主要在数据并行方式 <a class="header-anchor" href="#_1-4-a2c-与-a3c-的差异主要在数据并行方式" aria-label="Permalink to &quot;1.4 A2C 与 A3C 的差异主要在数据并行方式&quot;">​</a></h3><p>A3C（异步优势演员—评论家）让多个工作进程异步更新共享参数，A2C（同步优势演员—评论家）同步收集批次后更新。二者都建立在演员、评论家和优势估计之上。</p><p><img src="'+o+'" alt="Actor-Critic 用评论家评价演员采样的动作"></p><h2 id="二、为什么-reinforce-需要评论家" tabindex="-1">二、为什么 REINFORCE 需要评论家 <a class="header-anchor" href="#二、为什么-reinforce-需要评论家" aria-label="Permalink to &quot;二、为什么 REINFORCE 需要评论家&quot;">​</a></h2><h3 id="_2-1-完整回报到达太晚" tabindex="-1">2.1 完整回报到达太晚 <a class="header-anchor" href="#_2-1-完整回报到达太晚" aria-label="Permalink to &quot;2.1 完整回报到达太晚&quot;">​</a></h3><p>回合可能持续数百或数千步，早期动作必须等待终止才能获得更新。持续任务甚至没有自然终点，纯回合式更新不够自然。</p><h3 id="_2-2-蒙特卡洛回报包含大量随机性" tabindex="-1">2.2 蒙特卡洛回报包含大量随机性 <a class="header-anchor" href="#_2-2-蒙特卡洛回报包含大量随机性" aria-label="Permalink to &quot;2.2 蒙特卡洛回报包含大量随机性&quot;">​</a></h3><p>同一个状态动作之后，环境噪声、后续随机策略和其他参与者行为都会改变最终回报。把整段随机结果都归到当前动作，梯度方差很高。</p><h3 id="_2-3-状态基线可以由数据学习" tabindex="-1">2.3 状态基线可以由数据学习 <a class="header-anchor" href="#_2-3-状态基线可以由数据学习" aria-label="Permalink to &quot;2.3 状态基线可以由数据学习&quot;">​</a></h3><p>评论家估计当前策略从状态出发的通常回报。实际结果减去这一基线，就能判断采样动作是优于还是劣于常态。</p><h2 id="三、演员和评论家分别学什么" tabindex="-1">三、演员和评论家分别学什么 <a class="header-anchor" href="#三、演员和评论家分别学什么" aria-label="Permalink to &quot;三、演员和评论家分别学什么&quot;">​</a></h2><h3 id="_3-1-演员参数控制行为分布" tabindex="-1">3.1 演员参数控制行为分布 <a class="header-anchor" href="#_3-1-演员参数控制行为分布" aria-label="Permalink to &quot;3.1 演员参数控制行为分布&quot;">​</a></h3><p>演员参数 (\\theta) 决定 (\\pi_\\theta(a|s))。离散动作输出分类概率，连续动作输出均值、尺度或更复杂分布参数。</p><h3 id="_3-2-评论家参数拟合当前策略价值" tabindex="-1">3.2 评论家参数拟合当前策略价值 <a class="header-anchor" href="#_3-2-评论家参数拟合当前策略价值" aria-label="Permalink to &quot;3.2 评论家参数拟合当前策略价值&quot;">​</a></h3><p>评论家参数 (\\phi) 可表示 (V_\\phi(s))，目标是近似在当前演员策略下从状态出发的期望回报。</p><h3 id="_3-3-两者优化目标不同" tabindex="-1">3.3 两者优化目标不同 <a class="header-anchor" href="#_3-3-两者优化目标不同" aria-label="Permalink to &quot;3.3 两者优化目标不同&quot;">​</a></h3><p>演员最大化策略目标，评论家最小化价值预测损失。即使共享前端特征，输出头、损失项和梯度职责仍应清楚区分。</p><h3 id="_3-4-评论家不是安全裁判" tabindex="-1">3.4 评论家不是安全裁判 <a class="header-anchor" href="#_3-4-评论家不是安全裁判" aria-label="Permalink to &quot;3.4 评论家不是安全裁判&quot;">​</a></h3><p>评论家只学习奖励定义和训练分布下的期望价值。它没有独立安全权威，错误高分也不能绕过规则约束与后备控制。</p><h2 id="四、一步-td-目标怎样训练评论家" tabindex="-1">四、一步 TD 目标怎样训练评论家 <a class="header-anchor" href="#四、一步-td-目标怎样训练评论家" aria-label="Permalink to &quot;四、一步 TD 目标怎样训练评论家&quot;">​</a></h2><h3 id="_4-1-非终止转移使用下一状态自举" tabindex="-1">4.1 非终止转移使用下一状态自举 <a class="header-anchor" href="#_4-1-非终止转移使用下一状态自举" aria-label="Permalink to &quot;4.1 非终止转移使用下一状态自举&quot;">​</a></h3><p>$$ Y_t^V=R_{t+1}+\\gamma V_\\phi(S_{t+1}) $$</p><p>实践中计算目标时常停止梯度，使评论家回归阶段性目标，而不是同时修改等式两端。</p><h3 id="_4-2-自然终止时去掉下一状态价值" tabindex="-1">4.2 自然终止时去掉下一状态价值 <a class="header-anchor" href="#_4-2-自然终止时去掉下一状态价值" aria-label="Permalink to &quot;4.2 自然终止时去掉下一状态价值&quot;">​</a></h3><p>若 (S_{t+1}) 是任务定义的终止状态，目标只剩即时奖励。外部时间截断则通常保留自举，具体语义与前文 DQN 相同。</p><h3 id="_4-3-评论家损失是回归误差" tabindex="-1">4.3 评论家损失是回归误差 <a class="header-anchor" href="#_4-3-评论家损失是回归误差" aria-label="Permalink to &quot;4.3 评论家损失是回归误差&quot;">​</a></h3><p>$$ L_V(\\phi)=\\frac{1}{2}\\left(Y_t^V-V_\\phi(S_t)\\right)^2 $$</p><p>可使用均方误差或稳健损失，但损失选择不能修复错误的目标和终止掩码。</p><h2 id="五、td-误差怎样评价动作" tabindex="-1">五、TD 误差怎样评价动作 <a class="header-anchor" href="#五、td-误差怎样评价动作" aria-label="Permalink to &quot;五、TD 误差怎样评价动作&quot;">​</a></h2><h3 id="_5-1-误差比较实际一步结果与原预期" tabindex="-1">5.1 误差比较实际一步结果与原预期 <a class="header-anchor" href="#_5-1-误差比较实际一步结果与原预期" aria-label="Permalink to &quot;5.1 误差比较实际一步结果与原预期&quot;">​</a></h3><p>若奖励加下一状态价值高于当前状态预测，(\\delta_t&gt;0)，说明这次转移比评论家原先预期更好。</p><h3 id="_5-2-它是优势的单样本估计" tabindex="-1">5.2 它是优势的单样本估计 <a class="header-anchor" href="#_5-2-它是优势的单样本估计" aria-label="Permalink to &quot;5.2 它是优势的单样本估计&quot;">​</a></h3><p>对当前策略条件期望而言，(R_{t+1}+\\gamma V^\\pi(S_{t+1})-V^\\pi(S_t)) 与优势相关。实际训练使用近似价值，因此只是带误差的样本估计。</p><h3 id="_5-3-正负误差驱动演员方向" tabindex="-1">5.3 正负误差驱动演员方向 <a class="header-anchor" href="#_5-3-正负误差驱动演员方向" aria-label="Permalink to &quot;5.3 正负误差驱动演员方向&quot;">​</a></h3><p>演员梯度可写为：</p><p>$$ g_\\theta=\\delta_t\\nabla_\\theta\\log\\pi_\\theta(A_t|S_t) $$</p><p>正误差提高已采样动作概率，负误差降低概率。</p><p><img src="'+h+'" alt="一步 TD 误差同时训练评论家并评价演员动作"></p><h2 id="六、一次在线更新怎样发生" tabindex="-1">六、一次在线更新怎样发生 <a class="header-anchor" href="#六、一次在线更新怎样发生" aria-label="Permalink to &quot;六、一次在线更新怎样发生&quot;">​</a></h2><h3 id="_6-1-演员根据当前策略采样动作" tabindex="-1">6.1 演员根据当前策略采样动作 <a class="header-anchor" href="#_6-1-演员根据当前策略采样动作" aria-label="Permalink to &quot;6.1 演员根据当前策略采样动作&quot;">​</a></h3><p>保存动作的对数概率和策略熵，执行环境后获得奖励、下一状态、自然终止与截断标记。</p><h3 id="_6-2-评论家计算目标和-td-误差" tabindex="-1">6.2 评论家计算目标和 TD 误差 <a class="header-anchor" href="#_6-2-评论家计算目标和-td-误差" aria-label="Permalink to &quot;6.2 评论家计算目标和 TD 误差&quot;">​</a></h3><p>用当前或延迟的价值参数计算下一状态价值，根据终止语义构造目标，再得到 (\\delta_t)。</p><h3 id="_6-3-评论家先拟合价值目标" tabindex="-1">6.3 评论家先拟合价值目标 <a class="header-anchor" href="#_6-3-评论家先拟合价值目标" aria-label="Permalink to &quot;6.3 评论家先拟合价值目标&quot;">​</a></h3><p>最小化价值损失，使 (V_\\phi(S_t)) 更接近一步目标。实现可以同一批次联合反向传播，但逻辑职责仍是价值回归。</p><h3 id="_6-4-演员使用停止梯度的优势" tabindex="-1">6.4 演员使用停止梯度的优势 <a class="header-anchor" href="#_6-4-演员使用停止梯度的优势" aria-label="Permalink to &quot;6.4 演员使用停止梯度的优势&quot;">​</a></h3><p>优势权重通常从评论家计算图分离，避免演员损失通过优势分支意外更新评论家或用策略损失扭曲价值目标。</p><h3 id="_6-5-加入熵奖励维持探索" tabindex="-1">6.5 加入熵奖励维持探索 <a class="header-anchor" href="#_6-5-加入熵奖励维持探索" aria-label="Permalink to &quot;6.5 加入熵奖励维持探索&quot;">​</a></h3><p>演员目标常加入策略熵项，延缓分布过早塌缩。熵系数必须与动作空间和奖励尺度一起调节。</p><p><img src="'+l+'" alt="Actor-Critic 每轮交互连接演员、环境和评论家更新"></p><h2 id="七、一步优势有什么偏差—方差权衡" tabindex="-1">七、一步优势有什么偏差—方差权衡 <a class="header-anchor" href="#七、一步优势有什么偏差—方差权衡" aria-label="Permalink to &quot;七、一步优势有什么偏差—方差权衡&quot;">​</a></h2><h3 id="_7-1-一步自举方差较低" tabindex="-1">7.1 一步自举方差较低 <a class="header-anchor" href="#_7-1-一步自举方差较低" aria-label="Permalink to &quot;7.1 一步自举方差较低&quot;">​</a></h3><p>只使用一个随机奖励和下一状态价值，避免把整条后续轨迹的噪声全部纳入当前权重。</p><h3 id="_7-2-价值误差会产生偏差" tabindex="-1">7.2 价值误差会产生偏差 <a class="header-anchor" href="#_7-2-价值误差会产生偏差" aria-label="Permalink to &quot;7.2 价值误差会产生偏差&quot;">​</a></h3><p>评论家训练不足、函数表达不够或分布发生变化时，下一状态价值可能不准。演员会把这种误判当作动作优劣信号。</p><h3 id="_7-3-多步回报提供中间选择" tabindex="-1">7.3 多步回报提供中间选择 <a class="header-anchor" href="#_7-3-多步回报提供中间选择" aria-label="Permalink to &quot;7.3 多步回报提供中间选择&quot;">​</a></h3><p>可以收集 n 步真实奖励后再自举，用更多真实数据降低价值依赖，同时承担更高方差和更新延迟。</p><h3 id="_7-4-gae-进一步连续调节" tabindex="-1">7.4 GAE 进一步连续调节 <a class="header-anchor" href="#_7-4-gae-进一步连续调节" aria-label="Permalink to &quot;7.4 GAE 进一步连续调节&quot;">​</a></h3><p>Generalized Advantage Estimation（广义优势估计，GAE）按 ((\\gamma\\lambda)^l) 加权未来 TD 误差，在一步估计与较长回报之间调节偏差和方差。</p><h2 id="八、gae-怎样组合多步-td-误差" tabindex="-1">八、GAE 怎样组合多步 TD 误差 <a class="header-anchor" href="#八、gae-怎样组合多步-td-误差" aria-label="Permalink to &quot;八、GAE 怎样组合多步 TD 误差&quot;">​</a></h2><h3 id="_8-1-从每步-td-残差开始" tabindex="-1">8.1 从每步 TD 残差开始 <a class="header-anchor" href="#_8-1-从每步-td-残差开始" aria-label="Permalink to &quot;8.1 从每步 TD 残差开始&quot;">​</a></h3><p>$$ \\delta_t=R_{t+1}+\\gamma V(S_{t+1})-V(S_t) $$</p><h3 id="_8-2-优势是衰减残差之和" tabindex="-1">8.2 优势是衰减残差之和 <a class="header-anchor" href="#_8-2-优势是衰减残差之和" aria-label="Permalink to &quot;8.2 优势是衰减残差之和&quot;">​</a></h3><p>$$ \\hat A_t^{GAE(\\gamma,\\lambda)}=\\sum_{l=0}^{\\infty}(\\gamma\\lambda)^l\\delta_{t+l} $$</p><p>(\\lambda) 越小越接近一步 TD，越接近一越强调长时序信息。</p><h3 id="_8-3-终止与批次边界不能混淆" tabindex="-1">8.3 终止与批次边界不能混淆 <a class="header-anchor" href="#_8-3-终止与批次边界不能混淆" aria-label="Permalink to &quot;8.3 终止与批次边界不能混淆&quot;">​</a></h3><p>自然终止后残差链停止；采样批次仅因长度切断时，末端通常用评论家价值自举。错误处理会使每个批次末尾都出现假终点。</p><h3 id="_8-4-gae-不是新的奖励函数" tabindex="-1">8.4 GAE 不是新的奖励函数 <a class="header-anchor" href="#_8-4-gae-不是新的奖励函数" aria-label="Permalink to &quot;8.4 GAE 不是新的奖励函数&quot;">​</a></h3><p>它是优势估计器，用来构造策略梯度权重。(\\gamma) 和 (\\lambda) 改变估计时域与统计性质，不应被解释成安全约束系数。</p><p><img src="'+n+'" alt="GAE 把未来 TD 误差按折扣和 λ 衰减组合"></p><h2 id="九、共享网络还是分离网络" tabindex="-1">九、共享网络还是分离网络 <a class="header-anchor" href="#九、共享网络还是分离网络" aria-label="Permalink to &quot;九、共享网络还是分离网络&quot;">​</a></h2><h3 id="_9-1-共享骨干可以减少计算" tabindex="-1">9.1 共享骨干可以减少计算 <a class="header-anchor" href="#_9-1-共享骨干可以减少计算" aria-label="Permalink to &quot;9.1 共享骨干可以减少计算&quot;">​</a></h3><p>演员与评论家输入相同状态时，可共享特征提取层，再分出策略头和价值头。图像输入尤其能节省大量卷积计算。</p><h3 id="_9-2-两种损失可能争夺共享表示" tabindex="-1">9.2 两种损失可能争夺共享表示 <a class="header-anchor" href="#_9-2-两种损失可能争夺共享表示" aria-label="Permalink to &quot;9.2 两种损失可能争夺共享表示&quot;">​</a></h3><p>策略希望表示有利于动作区分，价值希望表示有利于回报回归。梯度方向冲突时，共享层可能使两项任务互相干扰。</p><h3 id="_9-3-分离网络更容易诊断" tabindex="-1">9.3 分离网络更容易诊断 <a class="header-anchor" href="#_9-3-分离网络更容易诊断" aria-label="Permalink to &quot;9.3 分离网络更容易诊断&quot;">​</a></h3><p>完全分离增加参数和计算，却能独立设置学习率、归一化与网络容量，便于定位演员或评论家谁先失稳。</p><h3 id="_9-4-选择应通过消融验证" tabindex="-1">9.4 选择应通过消融验证 <a class="header-anchor" href="#_9-4-选择应通过消融验证" aria-label="Permalink to &quot;9.4 选择应通过消融验证&quot;">​</a></h3><p>不能因为输入相同就断言共享一定更好。应在相同交互预算下比较回报、价值误差、策略熵、梯度相似性和训练成本。</p><h2 id="十、两个学习率为什么需要分别管理" tabindex="-1">十、两个学习率为什么需要分别管理 <a class="header-anchor" href="#十、两个学习率为什么需要分别管理" aria-label="Permalink to &quot;十、两个学习率为什么需要分别管理&quot;">​</a></h2><h3 id="_10-1-评论家太慢会提供过时评价" tabindex="-1">10.1 评论家太慢会提供过时评价 <a class="header-anchor" href="#_10-1-评论家太慢会提供过时评价" aria-label="Permalink to &quot;10.1 评论家太慢会提供过时评价&quot;">​</a></h3><p>演员不断变化，而评论家还没拟合当前策略，优势可能长期带系统偏差，演员在错误方向上加速更新。</p><h3 id="_10-2-评论家太快也可能追逐噪声" tabindex="-1">10.2 评论家太快也可能追逐噪声 <a class="header-anchor" href="#_10-2-评论家太快也可能追逐噪声" aria-label="Permalink to &quot;10.2 评论家太快也可能追逐噪声&quot;">​</a></h3><p>对小批次反复拟合会让价值函数过拟合当前轨迹，TD 误差表面变小，却不能泛化到下一批状态。</p><h3 id="_10-3-演员太快会让数据迅速过时" tabindex="-1">10.3 演员太快会让数据迅速过时 <a class="header-anchor" href="#_10-3-演员太快会让数据迅速过时" aria-label="Permalink to &quot;10.3 演员太快会让数据迅速过时&quot;">​</a></h3><p>一次策略改变过大后，当前批次不再代表新策略，评论家也需要重新适应。后续 PPO 正是针对策略步幅过大的问题。</p><h3 id="_10-4-更新比率必须明确记录" tabindex="-1">10.4 更新比率必须明确记录 <a class="header-anchor" href="#_10-4-更新比率必须明确记录" aria-label="Permalink to &quot;10.4 更新比率必须明确记录&quot;">​</a></h3><p>每批演员更新次数、评论家更新次数和环境步数决定训练动力学。仅报告两个学习率不足以复现实验。</p><h2 id="十一、a2c-与-a3c-到底有什么不同" tabindex="-1">十一、A2C 与 A3C 到底有什么不同 <a class="header-anchor" href="#十一、a2c-与-a3c-到底有什么不同" aria-label="Permalink to &quot;十一、A2C 与 A3C 到底有什么不同&quot;">​</a></h2><h3 id="_11-1-a3c-使用异步工作进程" tabindex="-1">11.1 A3C 使用异步工作进程 <a class="header-anchor" href="#_11-1-a3c-使用异步工作进程" aria-label="Permalink to &quot;11.1 A3C 使用异步工作进程&quot;">​</a></h3><p>多个 Actor-Learner（演员—学习器）在不同环境副本中采样，并异步把梯度应用到共享参数。数据多样性有助于降低强时间相关。</p><h3 id="_11-2-a2c-使用同步批次更新" tabindex="-1">11.2 A2C 使用同步批次更新 <a class="header-anchor" href="#_11-2-a2c-使用同步批次更新" aria-label="Permalink to &quot;11.2 A2C 使用同步批次更新&quot;">​</a></h3><p>多个环境同时运行，等待各环境收集固定步数后合并批次，再执行一次同步优化。实现更容易利用现代张量硬件。</p><h3 id="_11-3-异步不等于完全无偏" tabindex="-1">11.3 异步不等于完全无偏 <a class="header-anchor" href="#_11-3-异步不等于完全无偏" aria-label="Permalink to &quot;11.3 异步不等于完全无偏&quot;">​</a></h3><p>A3C 工作进程使用的本地参数可能落后于共享参数，梯度存在陈旧性。并行能改善吞吐和多样性，不自动提供理论收敛保证。</p><h3 id="_11-4-名称不能替代实现说明" tabindex="-1">11.4 名称不能替代实现说明 <a class="header-anchor" href="#_11-4-名称不能替代实现说明" aria-label="Permalink to &quot;11.4 名称不能替代实现说明&quot;">​</a></h3><p>必须报告环境数、每段步数、同步方式、优势估计、熵系数和梯度裁剪。只写“A2C”不足以确定训练算法。</p><h2 id="十二、策略熵和价值损失怎样联合" tabindex="-1">十二、策略熵和价值损失怎样联合 <a class="header-anchor" href="#十二、策略熵和价值损失怎样联合" aria-label="Permalink to &quot;十二、策略熵和价值损失怎样联合&quot;">​</a></h2><h3 id="_12-1-常见总损失由多项组成" tabindex="-1">12.1 常见总损失由多项组成 <a class="header-anchor" href="#_12-1-常见总损失由多项组成" aria-label="Permalink to &quot;12.1 常见总损失由多项组成&quot;">​</a></h3><p>可写为：</p><p>$$ L=L_{policy}+c_vL_{value}-c_e\\mathcal H(\\pi) $$</p><p>其中价值系数和熵系数控制不同目标对共享参数的影响。</p><h3 id="_12-2-各项尺度可能差异很大" tabindex="-1">12.2 各项尺度可能差异很大 <a class="header-anchor" href="#_12-2-各项尺度可能差异很大" aria-label="Permalink to &quot;12.2 各项尺度可能差异很大&quot;">​</a></h3><p>奖励缩放会直接改变优势和价值损失，却不同比例改变熵。换任务时沿用同一系数可能导致某一项完全主导梯度。</p><h3 id="_12-3-应分别记录每项损失" tabindex="-1">12.3 应分别记录每项损失 <a class="header-anchor" href="#_12-3-应分别记录每项损失" aria-label="Permalink to &quot;12.3 应分别记录每项损失&quot;">​</a></h3><p>只记录总损失看不出策略项、价值项还是熵项异常。还应监控价值解释方差、策略熵、梯度范数和回报。</p><h2 id="十三、评论家失效时会出现什么" tabindex="-1">十三、评论家失效时会出现什么 <a class="header-anchor" href="#十三、评论家失效时会出现什么" aria-label="Permalink to &quot;十三、评论家失效时会出现什么&quot;">​</a></h2><h3 id="_13-1-价值预测爆炸" tabindex="-1">13.1 价值预测爆炸 <a class="header-anchor" href="#_13-1-价值预测爆炸" aria-label="Permalink to &quot;13.1 价值预测爆炸&quot;">​</a></h3><p>奖励尺度过大、终止掩码错误或学习率过高会让价值持续增长，优势也随之异常，演员更新迅速失控。</p><h3 id="_13-2-价值损失很低但策略不进步" tabindex="-1">13.2 价值损失很低但策略不进步 <a class="header-anchor" href="#_13-2-价值损失很低但策略不进步" aria-label="Permalink to &quot;13.2 价值损失很低但策略不进步&quot;">​</a></h3><p>评论家可能只拟合狭窄的当前数据，或者回报本身缺乏动作区分度。低损失不代表优势对策略有用。</p><h3 id="_13-3-优势长期只有同一符号" tabindex="-1">13.3 优势长期只有同一符号 <a class="header-anchor" href="#_13-3-优势长期只有同一符号" aria-label="Permalink to &quot;13.3 优势长期只有同一符号&quot;">​</a></h3><p>若几乎全正或全负，应检查基线、回报归一化和终止处理。优势通常应围绕相对表现分布，而不是永远奖励或惩罚所有动作。</p><h3 id="_13-4-策略熵快速归零" tabindex="-1">13.4 策略熵快速归零 <a class="header-anchor" href="#_13-4-策略熵快速归零" aria-label="Permalink to &quot;13.4 策略熵快速归零&quot;">​</a></h3><p>过大演员步幅、过弱熵系数或错误优势尺度会让策略过早确定，随后动作覆盖不足，评论家也只看到狭窄分布。</p><h2 id="十四、自动驾驶中演员与评论家怎样分工" tabindex="-1">十四、自动驾驶中演员与评论家怎样分工 <a class="header-anchor" href="#十四、自动驾驶中演员与评论家怎样分工" aria-label="Permalink to &quot;十四、自动驾驶中演员与评论家怎样分工&quot;">​</a></h2><h3 id="_14-1-演员提出连续控制或轨迹参数" tabindex="-1">14.1 演员提出连续控制或轨迹参数 <a class="header-anchor" href="#_14-1-演员提出连续控制或轨迹参数" aria-label="Permalink to &quot;14.1 演员提出连续控制或轨迹参数&quot;">​</a></h3><p>演员可以输出曲率、加速度或候选轨迹分布，减少动作离散化误差。</p><h3 id="_14-2-评论家评价长期任务回报" tabindex="-1">14.2 评论家评价长期任务回报 <a class="header-anchor" href="#_14-2-评论家评价长期任务回报" aria-label="Permalink to &quot;14.2 评论家评价长期任务回报&quot;">​</a></h3><p>评论家学习进度、舒适性和风险惩罚综合后的期望回报，但它只能反映训练目标，无法独立证明约束满足。</p><h3 id="_14-3-安全层仍需独立于评论家" tabindex="-1">14.3 安全层仍需独立于评论家 <a class="header-anchor" href="#_14-3-安全层仍需独立于评论家" aria-label="Permalink to &quot;14.3 安全层仍需独立于评论家&quot;">​</a></h3><p>Safety Shield（安全屏蔽）、Control Barrier Function（控制屏障函数）或可验证后备控制器应检查演员动作。评论家的高价值不能作为解除约束的依据。</p><h3 id="_14-4-记录安全层介入后的真实动作" tabindex="-1">14.4 记录安全层介入后的真实动作 <a class="header-anchor" href="#_14-4-记录安全层介入后的真实动作" aria-label="Permalink to &quot;14.4 记录安全层介入后的真实动作&quot;">​</a></h3><p>若演员输出被安全层修改，训练数据必须区分提议动作与实际执行动作。否则策略对数概率与环境转移对应不上，梯度语义可能失真。</p><p><img src="'+c+'" alt="自动驾驶 Actor-Critic 外部仍需安全执行链"></p><h2 id="十五、一个最小实验怎样搭建" tabindex="-1">十五、一个最小实验怎样搭建 <a class="header-anchor" href="#十五、一个最小实验怎样搭建" aria-label="Permalink to &quot;十五、一个最小实验怎样搭建&quot;">​</a></h2><h3 id="_15-1-用同一环境对比-reinforce" tabindex="-1">15.1 用同一环境对比 REINFORCE <a class="header-anchor" href="#_15-1-用同一环境对比-reinforce" aria-label="Permalink to &quot;15.1 用同一环境对比 REINFORCE&quot;">​</a></h3><p>固定网络规模、交互预算和随机种子，对比完整回报、一步 Actor-Critic 与 GAE 版本，观察样本效率和方差变化。</p><h3 id="_15-2-单独验证评论家" tabindex="-1">15.2 单独验证评论家 <a class="header-anchor" href="#_15-2-单独验证评论家" aria-label="Permalink to &quot;15.2 单独验证评论家&quot;">​</a></h3><p>用采样回报估计固定评估状态的实现价值，比较评论家预测，绘制校准误差和分布外误差，不能只看训练价值损失。</p><h3 id="_15-3-做共享与分离网络消融" tabindex="-1">15.3 做共享与分离网络消融 <a class="header-anchor" href="#_15-3-做共享与分离网络消融" aria-label="Permalink to &quot;15.3 做共享与分离网络消融&quot;">​</a></h3><p>控制总参数量或明确报告差异，比较训练速度、梯度冲突与最终回报，避免把容量增加误判成架构优势。</p><h3 id="_15-4-使用多随机种子" tabindex="-1">15.4 使用多随机种子 <a class="header-anchor" href="#_15-4-使用多随机种子" aria-label="Permalink to &quot;15.4 使用多随机种子&quot;">​</a></h3><p>Actor-Critic 仍然对初始化和采样敏感。报告中位数、四分位范围、失败率和达到阈值所需环境步数。</p><h2 id="十六、最常见的实现错误" tabindex="-1">十六、最常见的实现错误 <a class="header-anchor" href="#十六、最常见的实现错误" aria-label="Permalink to &quot;十六、最常见的实现错误&quot;">​</a></h2><h3 id="_16-1-优势没有停止梯度" tabindex="-1">16.1 优势没有停止梯度 <a class="header-anchor" href="#_16-1-优势没有停止梯度" aria-label="Permalink to &quot;16.1 优势没有停止梯度&quot;">​</a></h3><p>演员损失中的优势通常视为权重。若未分离，策略损失可能通过价值输出反向传播，混淆演员与评论家目标。</p><h3 id="_16-2-把截断当作自然终止" tabindex="-1">16.2 把截断当作自然终止 <a class="header-anchor" href="#_16-2-把截断当作自然终止" aria-label="Permalink to &quot;16.2 把截断当作自然终止&quot;">​</a></h3><p>固定采样长度、时间上限和真正失败必须区分。批次末尾的非终止状态通常需要价值自举。</p><h3 id="_16-3-更新顺序依赖同一计算图" tabindex="-1">16.3 更新顺序依赖同一计算图 <a class="header-anchor" href="#_16-3-更新顺序依赖同一计算图" aria-label="Permalink to &quot;16.3 更新顺序依赖同一计算图&quot;">​</a></h3><p>先更新评论家参数后再对旧图执行演员反向传播，可能触发版本错误或使用不一致参数。应清楚组织前向、分离和优化步骤。</p><h3 id="_16-4-共享层被两个优化器重复更新" tabindex="-1">16.4 共享层被两个优化器重复更新 <a class="header-anchor" href="#_16-4-共享层被两个优化器重复更新" aria-label="Permalink to &quot;16.4 共享层被两个优化器重复更新&quot;">​</a></h3><p>若演员和评论家优化器都包含同一共享参数，一轮可能意外更新两次。共享参数的所有权与梯度合并方式必须明确。</p><h2 id="十七、学到什么程度才算掌握" tabindex="-1">十七、学到什么程度才算掌握 <a class="header-anchor" href="#十七、学到什么程度才算掌握" aria-label="Permalink to &quot;十七、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_17-1-能画出双网络的数据流" tabindex="-1">17.1 能画出双网络的数据流 <a class="header-anchor" href="#_17-1-能画出双网络的数据流" aria-label="Permalink to &quot;17.1 能画出双网络的数据流&quot;">​</a></h3><p>应能说明状态进入哪个网络、动作从哪里采样、价值目标如何计算、优势在哪里停止梯度，以及各优化器更新哪些参数。</p><h3 id="_17-2-能解释偏差与方差交换" tabindex="-1">17.2 能解释偏差与方差交换 <a class="header-anchor" href="#_17-2-能解释偏差与方差交换" aria-label="Permalink to &quot;17.2 能解释偏差与方差交换&quot;">​</a></h3><p>蒙特卡洛回报方差高但少依赖估计，一步 TD 方差低却引入自举偏差，GAE 用 (\\lambda) 在两者之间调节。</p><h3 id="_17-3-能区分-a2c-与-a3c-的并行语义" tabindex="-1">17.3 能区分 A2C 与 A3C 的并行语义 <a class="header-anchor" href="#_17-3-能区分-a2c-与-a3c-的并行语义" aria-label="Permalink to &quot;17.3 能区分 A2C 与 A3C 的并行语义&quot;">​</a></h3><p>同步或异步改变数据收集与参数更新时序，但不会改变演员、评论家和优势估计的基本角色。</p><h3 id="_17-4-能准备进入-ppo" tabindex="-1">17.4 能准备进入 PPO <a class="header-anchor" href="#_17-4-能准备进入-ppo" aria-label="Permalink to &quot;17.4 能准备进入 PPO&quot;">​</a></h3><p>下一篇将保存采样时的旧策略概率，使用新旧概率比率复用同一批同策略数据，并通过裁剪目标限制更新激励。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter9/chapter9.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第九章演员—评论家算法</a></p><p><a href="https://spinningup.openai.com/en/latest/algorithms/vpg.html" target="_blank" rel="noreferrer">OpenAI Spinning Up Vanilla Policy Gradient（基础策略梯度）</a></p><p><a href="https://arxiv.org/abs/1602.01783" target="_blank" rel="noreferrer">Mnih 等《Asynchronous Methods for Deep Reinforcement Learning》</a></p><p><a href="https://arxiv.org/abs/1506.02438" target="_blank" rel="noreferrer">Schulman 等《High-Dimensional Continuous Control Using Generalized Advantage Estimation》</a></p><p><a href="http://incompleteideas.net/book/the-book-2nd.html" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction》第二版第十三章</a></p>',169)])])}const P=e(d,[["render",s]]);export{f as __pageData,P as default};
